func TestWorkerPool_BoundedConcurrency(t *testing.T) {
	const maxWorkers = 3
	const totalTasks = 20

	wp := NewWorkerPool(maxWorkers)

	var active int32
	var maxObserved int32
	var completed int32

	for i := 0; i < totalTasks; i++ {
		wp.Submit(func() {
			cur := atomic.AddInt32(&active, 1)
			for {
				prev := atomic.LoadInt32(&maxObserved)
				if cur <= prev || atomic.CompareAndSwapInt32(&maxObserved, prev, cur) {
					break
				}
			}
			time.Sleep(5 * time.Millisecond)
			atomic.AddInt32(&active, -1)
			atomic.AddInt32(&completed, 1)
		})
	}

	wp.StopWait()

	if got := atomic.LoadInt32(&completed); got != totalTasks {
		t.Fatalf("expected %d completed tasks, got %d", totalTasks, got)
	}
	if got := atomic.LoadInt32(&maxObserved); got > maxWorkers {
		t.Fatalf("expected max concurrency <= %d, got %d", maxWorkers, got)
	}
	if got := atomic.LoadInt32(&maxObserved); got < 2 {
		t.Fatalf("expected parallel execution (maxObserved >= 2), got %d", got)
	}
}

func TestWorkerPool_ClampNonPositiveWorkers(t *testing.T) {
	for _, maxWorkers := range []int{0, -1, -10} {
		wp := NewWorkerPool(maxWorkers)
		var active int32
		var maxObserved int32
		var completed int32

		for i := 0; i < 5; i++ {
			wp.Submit(func() {
				cur := atomic.AddInt32(&active, 1)
				for {
					prev := atomic.LoadInt32(&maxObserved)
					if cur <= prev || atomic.CompareAndSwapInt32(&maxObserved, prev, cur) {
						break
					}
				}
				time.Sleep(2 * time.Millisecond)
				atomic.AddInt32(&active, -1)
				atomic.AddInt32(&completed, 1)
			})
		}

		wp.StopWait()

		if got := atomic.LoadInt32(&completed); got != 5 {
			t.Fatalf("maxWorkers=%d: expected 5 completed tasks, got %d", maxWorkers, got)
		}
		if got := atomic.LoadInt32(&maxObserved); got != 1 {
			t.Fatalf("maxWorkers=%d: expected max concurrency == 1, got %d", maxWorkers, got)
		}
	}
}

func TestWorkerPool_SubmitNilAndEmptyStopWait(t *testing.T) {
	wp := NewWorkerPool(2)
	// StopWait on empty pool should return immediately.
	wp.StopWait()

	// Submit(nil) should be a safe no-op.
	wp.Submit(nil)
	wp.StopWait()
}
